  const cellsOf = rows => { const c = new Set(); rows.forEach((r, y) => { for (let x = 0; x < 10; x++) if (r[x] === '#') c.add(y * 10 + x); }); return c; };
  // v5.06 (user: 出来るだけテンプレを全て入れたい): four.lol の各ページの fumen から作った開幕(下から合わせる・上と同じ判定)
