  let raf = 0, tick = 0;
  const loop = () => {
    raf = requestAnimationFrame(loop);
    try {
      for (const n of games) if (alive(n)) watch(n);
      if (++tick % 6 === 0) draw(false);   // 表示の更新は 10 回/秒
    } catch (e) { console.warn(TAG, e); }
  };
  raf = requestAnimationFrame(loop);

